// ============================================================
// DEDUP NODE - Triple-layer idempotency guard
// ============================================================
//
// LAYER 1: Outlook's own isRead flag (durable, survives restarts)
// LAYER 2: In-memory staticData.processedIds (fast, 7-day window)
// LAYER 3: Mark Email Read at end of pipeline flips isRead=true
//
// Any one layer surviving is enough to prevent duplicate drafts.
// ============================================================

const SEVEN_DAYS_MS = 7 * 24 * 60 * 60 * 1000;
const now = Date.now();
const item = $input.first().json;

// ---- LAYER 1: skip if Outlook already flagged the message read ----
// This is the single most important check for preventing duplicate drafts
// when the workflow is re-tested manually or n8n restarts and loses staticData.
if (item.isRead === true) {
  console.log('[Dedup] Outlook isRead=true - skipping');
  return [];
}

// ---- LAYER 2: in-memory rolling window ----
const staticData = $getWorkflowStaticData('global');
if (!staticData.processedIds) {
  staticData.processedIds = {};
}

// Garbage-collect entries older than 7 days to bound memory
for (const [id, timestamp] of Object.entries(staticData.processedIds)) {
  if (now - timestamp > SEVEN_DAYS_MS) {
    delete staticData.processedIds[id];
  }
}

// Dedup key resolution order: internetMessageId (RFC 2822, stable across
// forwards) > Graph id (stable per message) > messageId (last resort).
const dedupKey = item.internetMessageId || item.id || item.messageId;

// Fail-open: if we literally cannot identify the message, pass it through
// once but log loudly. Observability beats silent drops at the edge.
if (!dedupKey) {
  console.log('[Dedup] no ID on trigger output - passing through. Keys: ' + Object.keys(item).join(', '));
  return $input.all();
}

if (staticData.processedIds[dedupKey]) {
  console.log('[Dedup] already in processedIds - skipping: ' + dedupKey);
  return [];
}

return $input.all();

// ============================================================
// THREAD STRIPPER - Quoted-reply isolation
// ============================================================
// Extracts ONLY the newest message from the email body, discarding
// any quoted reply history. Required by strict enterprise data constraints:
// "If an email is part of a reply chain, only extract from the newest
// message and ignore the quoted history."
//
// Multi-lingual thread markers: English, Italian, German, French, Spanish,
// blockquotes, and ">" prefixed lines.
// ============================================================

const item = $input.first().json;

// --- Body extraction: try every known Outlook Trigger path ---
let body = '';
if (typeof item.body === 'string') body = item.body;
else if (item.body?.content) body = item.body.content;
else if (item.bodyPreview) body = item.bodyPreview;
else if (item.text) body = item.text;
else if (item.Body?.Content) body = item.Body.Content;

// Strip HTML tags & decode common entities
body = body.replace(/<[^>]*>/g, ' ')
  .replace(/&nbsp;/g, ' ')
  .replace(/&amp;/g, '&')
  .replace(/&lt;/g, '<')
  .replace(/&gt;/g, '>')
  .replace(/&#39;/g, "'")
  .replace(/&quot;/g, '"');

// --- Truncate at the earliest thread marker ---
const markers = [
  /On .+ wrote:/i,
  /From:.+?Sent:.+?Subject:/is,
  /Il giorno .+ ha scritto:/i,
  /Da:.+?Inviato:.+?Oggetto:/is,
  /Am .+ schrieb .+:/i,
  /Von:.+?Gesendet:.+?Betreff:/is,
  /Le .+ a ecrit :/i,
  /De :.+?Envoye :.+?Objet :/is,
  /El .+ escribio:/i,
  /De:.+?Enviado:.+?Asunto:/is,
  /(\n>\s.*){2,}/,
  /<blockquote/i
];
let earliestIndex = body.length;
for (const marker of markers) {
  const match = body.search(marker);
  if (match !== -1 && match < earliestIndex) earliestIndex = match;
}
const strippedBody = body.substring(0, earliestIndex).replace(/\s+/g, ' ').trim();

// --- Sender email: try every known path ---
const senderEmail =
  item.from?.emailAddress?.address ||
  item.sender?.emailAddress?.address ||
  item.from?.address ||
  item.fromEmail ||
  (typeof item.From === 'string' ? item.From : '') ||
  (typeof item.from === 'string' ? item.from : '') ||
  '';

// --- Sender name: try every known path, fall back to email local part ---
const senderName =
  item.from?.emailAddress?.name ||
  item.sender?.emailAddress?.name ||
  item.from?.name ||
  item.fromName ||
  (senderEmail ? senderEmail.split('@')[0] : 'Customer');

// --- Message IDs: keep both ---
// Graph `id` creates the reply draft. internetMessageId (RFC 2822) is dedup.
const messageId = item.id || item.messageId || '';
const internetMessageId = item.internetMessageId || messageId || '';

// --- Sanity checks ---
if (!strippedBody) {
  throw new Error('Thread Stripper: email body is empty. Check Outlook Trigger output.');
}
if (!senderEmail) {
  console.log('[Thread Stripper] WARNING: senderEmail is empty. Raw keys: ' + Object.keys(item).join(', '));
}
if (!internetMessageId) {
  console.log('[Thread Stripper] WARNING: no message ID found. Raw keys: ' + Object.keys(item).join(', '));
}

return [{
  json: {
    strippedBody,
    originalSubject: item.subject || item.Subject || '',
    senderEmail,
    senderName,
    internetMessageId,
    messageId
  }
}];

// ============================================================
// PARSE STAGE 1 JSON - Defense in depth + language safety net
// ============================================================
// Converts the Stage 1 LLM output into a strongly-typed classification.
// Fails CLOSED (intent=unknown) when LLM misbehaves.
//
// Layers:
//   1. Strip code fences
//   2. Extract outermost {...}
//   3. Validate intent against enum
//   4. Validate language against ISO 639-1 allowlist
//   5. HEURISTIC LANGUAGE OVERRIDE - catches the Italian->English bug
//      when the LLM incorrectly returns language="en" for a non-English body
// ============================================================

const item = $input.first().json;
let raw = (item.text || item.response || item.output || '').trim();

// LAYER 1: strip code fences anywhere in the output
raw = raw.replace(/```(?:json)?\s*/gi, '').replace(/```/g, '').trim();

// LAYER 2: extract outermost {...} even if LLM added prose
const firstBrace = raw.indexOf('{');
const lastBrace = raw.lastIndexOf('}');
if (firstBrace !== -1 && lastBrace > firstBrace) {
  raw = raw.substring(firstBrace, lastBrace + 1);
}

let parsed;
let parseOk = true;
try {
  parsed = JSON.parse(raw);
} catch (e) {
  parseOk = false;
  console.log('[Parse Stage 1] JSON parse failed. Raw preview: ' + raw.substring(0, 200));
  parsed = { intent: 'unknown', product_name: null, customer_name: null, language: 'en', confidence: 0 };
}

// LAYER 3: validate intent against allowed enum - fail closed to unknown
const ALLOWED_INTENTS = ['Availability_Status','Quantity_Inquiry','Incoming_Stock','Pricing_Request','Delivery_Tracking','unknown'];
if (!ALLOWED_INTENTS.includes(parsed.intent)) {
  console.log('[Parse Stage 1] invalid intent "' + parsed.intent + '" - forcing unknown');
  parsed.intent = 'unknown';
  parsed.confidence = 0;
}

// LAYER 4: validate language against ISO 639-1 allowlist
const ALLOWED_LANG = ['en','it','de','fr','es','pt','nl'];
let language = (parsed.language || '').toLowerCase().trim();

// LAYER 5: HEURISTIC LANGUAGE OVERRIDE
// If the LLM said "en" (or returned an invalid code) but the body contains
// strong lexical markers of a non-English language, override. This is the
// primary safety net for the Italian-email-gets-English-reply bug.
const prevData = $('Thread Stripper').first().json;
const bodyLower = (prevData.strippedBody || '').toLowerCase();

const LANG_MARKERS = {
  it: /\b(gentile|buongiorno|buonasera|cordiali saluti|grazie mille|la ringrazio|potrebbe|possiamo|quando arrivera|disponibilita|quanto costa|sono interessato|mi puo|mi potrebbe|in attesa|spedizione|fattura|preventivo|vorrei sapere|vorrei ordinare|vi scrivo)\b/i,
  de: /\b(sehr geehrte|guten tag|mit freundlichen grussen|mit freundlichen gruessen|bestellung|lieferung|rechnung|ich hatte gern|konnen sie|mochte ich|danke sehr|anfrage|verfugbar|lieferzeit|preisanfrage|angebot)\b/i,
  fr: /\b(bonjour|cordialement|je voudrais|pourriez-vous|merci beaucoup|livraison|commande|facture|disponibilite|combien coute|votre aide|je vous prie|veuillez|devis)\b/i,
  es: /\b(estimado|estimada|buenos dias|saludos cordiales|quisiera|podria|gracias por|entrega|pedido|factura|disponibilidad|cuanto cuesta|me gustaria|presupuesto|agradezco)\b/i,
  pt: /\b(caro cliente|bom dia|com os melhores cumprimentos|obrigado|obrigada|gostaria|poderia|entrega|encomenda|fatura|disponibilidade|quanto custa|orcamento)\b/i,
  nl: /\b(beste|goedendag|met vriendelijke groet|dank u wel|ik zou graag|kunt u|levering|bestelling|factuur|beschikbaarheid|prijs|offerte)\b/i
};

let detectedLang = null;
let bestScore = 0;
for (const [code, rx] of Object.entries(LANG_MARKERS)) {
  const matches = (bodyLower.match(new RegExp(rx.source, 'gi')) || []).length;
  if (matches > bestScore) {
    bestScore = matches;
    detectedLang = code;
  }
}

// Only override if: (a) we detected a clear non-English hit AND
// (b) the LLM's answer was either "en" or not in our allowlist.
if (detectedLang && bestScore >= 1 && (language === 'en' || !ALLOWED_LANG.includes(language))) {
  console.log('[Parse Stage 1] LANGUAGE OVERRIDE: LLM said "' + language + '", heuristic detected "' + detectedLang + '" (score=' + bestScore + ')');
  language = detectedLang;
}

// Final fallback to English if still invalid
if (!ALLOWED_LANG.includes(language)) {
  language = 'en';
}

return [{
  json: {
    intent: parsed.intent,
    product_name: parsed.product_name || null,
    customer_name: parsed.customer_name || null,
    language: language,
    confidence: typeof parsed.confidence === 'number' ? parsed.confidence : 0,
    parse_ok: parseOk,
    strippedBody: prevData.strippedBody,
    originalSubject: prevData.originalSubject,
    senderEmail: prevData.senderEmail,
    senderName: prevData.senderName,
    internetMessageId: prevData.internetMessageId,
    messageId: prevData.messageId
  }
}];

// ============================================================
// MATCHER - Deterministic database lookup
// ============================================================
// Two-tier matching (exact normalized, then bidirectional substring).
// Fails closed to route='not_found_draft' when no match found.
// NEVER fuzzy/vector match - the strict enterprise rule is zero hallucination.
// ============================================================

const classificationData = $('Parse Stage 1 JSON').first().json;
const intent = classificationData.intent;
const productQuery = (classificationData.product_name || '').toLowerCase().trim();
const customerQuery = (classificationData.customer_name || '').toLowerCase().trim();

let inventoryItems = [];
try { inventoryItems = $('Load Inventory').all().map(i => i.json); } catch(e) {}

let deliveryItems = [];
try { deliveryItems = $('Load Deliveries').all().map(i => i.json); } catch(e) {}

if (!productQuery) {
  return [{ json: { ...classificationData, route: 'clarification_draft', matchedProduct: null, matchedDelivery: null, match_tier: 'none' } }];
}

// Tier 1: exact normalized
let matchedProduct = inventoryItems.find(p => (p.Product_Name || '').toLowerCase().trim() === productQuery);
let matchTier = matchedProduct ? 'exact' : null;

// Tier 2: bidirectional substring
if (!matchedProduct) {
  matchedProduct = inventoryItems.find(p => {
    const name = (p.Product_Name || '').toLowerCase().trim();
    return name.includes(productQuery) || productQuery.includes(name);
  });
  matchTier = matchedProduct ? 'substring' : null;
}

if (!matchedProduct) {
  return [{ json: { ...classificationData, route: 'not_found_draft', matchedProduct: null, matchedDelivery: null, match_tier: 'none' } }];
}

// Delivery lookup for Delivery_Tracking intent
let matchedDelivery = null;
if (intent === 'Delivery_Tracking') {
  const productName = (matchedProduct.Product_Name || '').toLowerCase().trim();
  matchedDelivery = deliveryItems.find(d => {
    const dProduct = (d.Product_Name || '').toLowerCase().trim();
    const dCustomer = (d.Customer_Name || '').toLowerCase().trim();
    return (dProduct === productName || dProduct.includes(productQuery) || productQuery.includes(dProduct)) &&
           (!customerQuery || dCustomer === customerQuery || dCustomer.includes(customerQuery) || customerQuery.includes(dCustomer));
  });
  if (!matchedDelivery) {
    return [{ json: { ...classificationData, route: 'not_found_draft', matchedProduct, matchedDelivery: null, match_tier: matchTier } }];
  }
}

return [{ json: { ...classificationData, route: 'high_confidence', matchedProduct, matchedDelivery, match_tier: matchTier } }];

// ============================================================
// UNKNOWN PACKET - Ambiguous email handler
// ============================================================
// Emits route='clarification_draft' which triggers the Stage 2 LLM
// to draft a polite "could you clarify?" reply. Keeps the output
// shape symmetric with Matcher so downstream nodes don't branch.
// ============================================================

const item = $input.first().json;

return [{
  json: {
    ...item,
    route: 'clarification_draft',
    intent: 'unknown',
    matchedProduct: null,
    matchedDelivery: null,
    match_tier: 'none'
  }
}];

// ============================================================
// COMPOSE DATA PACKET - Strict field allowlist + personalization
// ============================================================
// Builds the `data` object with ONLY the fields the drafter is
// permitted to cite for the given intent. This is a hard boundary -
// the Stage 2 LLM never sees Discount_Pct, Category, internal SKU etc.
//
// Also extracts sender_first_name deterministically (not via LLM) so
// the drafter has a clean personalization value and never needs to
// emit [Sender Name] placeholders.
// ============================================================

const item = $input.first().json;
const { route, intent, matchedProduct, matchedDelivery } = item;

function extractFirstName(name, email) {
  if (name && typeof name === 'string') {
    let n = name.replace(/[<>"]/g, '').trim();
    if (n.includes('@')) n = n.split('@')[0];
    n = n.replace(/[._-]+/g, ' ').trim();
    if (n.length > 0) {
      const first = n.split(/\s+/)[0];
      return first.charAt(0).toUpperCase() + first.slice(1).toLowerCase();
    }
  }
  if (email) {
    const local = email.split('@')[0].replace(/[._-]+/g, ' ').trim();
    const first = local.split(/\s+/)[0];
    if (first) return first.charAt(0).toUpperCase() + first.slice(1).toLowerCase();
  }
  return '';
}
const senderFirstName = extractFirstName(item.senderName, item.senderEmail);

let data = {};
if (route === 'high_confidence' && matchedProduct) {
  switch (intent) {
    case 'Availability_Status':
      data = {
        product_name: matchedProduct.Product_Name,
        stock_status: matchedProduct.Stock_Status,
        next_arrival_date: matchedProduct.Next_Arrival_Date || null
      };
      break;
    case 'Quantity_Inquiry':
      data = {
        product_name: matchedProduct.Product_Name,
        stock_quantity: matchedProduct.Stock_Quantity,
        stock_status: matchedProduct.Stock_Status
      };
      break;
    case 'Incoming_Stock':
      data = {
        product_name: matchedProduct.Product_Name,
        next_arrival_date: matchedProduct.Next_Arrival_Date || null,
        stock_status: matchedProduct.Stock_Status
      };
      break;
    case 'Pricing_Request':
      data = {
        product_name: matchedProduct.Product_Name,
        unit_price: matchedProduct.Unit_Price
      };
      break;
    case 'Delivery_Tracking':
      data = {
        product_name: matchedProduct.Product_Name,
        order_id: matchedDelivery ? matchedDelivery.Order_ID : null,
        customer_name: matchedDelivery ? matchedDelivery.Customer_Name : null,
        quantity: matchedDelivery ? matchedDelivery.Quantity : null,
        delivery_eta: matchedDelivery ? matchedDelivery.Delivery_ETA : null,
        status: matchedDelivery ? matchedDelivery.Status : null
      };
      break;
  }
}

return [{
  json: {
    route,
    intent,
    language: item.language || 'en',
    data,
    sender_first_name: senderFirstName,
    senderEmail: item.senderEmail,
    senderName: item.senderName,
    originalSubject: item.originalSubject,
    internetMessageId: item.internetMessageId,
    messageId: item.messageId,
    strippedBody: item.strippedBody,
    confidence: item.confidence,
    match_tier: item.match_tier
  }
}];

// ============================================================
// SCRUB FORMAT - Post-LLM sanitization (last line of defense)
// ============================================================
// Three defense layers against template leakage:
//   Layer 1: Stage 2 prompt forbids markdown and placeholders
//   Layer 2: sender_first_name passed explicitly so LLM has no reason to emit [Sender Name]
//   Layer 3: THIS NODE - regex sweep catches anything that slipped through
//
// Also produces an HTML-safe version (draftBodyHtml) for future use
// if Create Outlook Draft is switched from bodyContentType=text to html.
// ============================================================

const item = $input.first().json;
let text = item.text || item.response || item.output || '';

// ---- strip markdown ----
text = text.replace(/```[\s\S]*?```/g, m => m.replace(/^```(?:\w*)?\n?/, '').replace(/\n?```$/, ''));
text = text.replace(/`/g, '');
text = text.replace(/^#{1,6}\s+/gm, '');
text = text.replace(/\*{1,2}([^*\n]+)\*{1,2}/g, '$1');
text = text.replace(/_{1,2}([^_\n]+)_{1,2}/g, '$1');
text = text.replace(/^[\s]*[-*+]\s+/gm, '');
text = text.replace(/^[\s]*\d+\.\s+/gm, '');

// ---- strip emoji ----
text = text.replace(/[\u{1F600}-\u{1F64F}\u{1F300}-\u{1F5FF}\u{1F680}-\u{1F6FF}\u{1F1E0}-\u{1F1FF}\u{2600}-\u{26FF}\u{2700}-\u{27BF}\u{FE00}-\u{FE0F}\u{1F900}-\u{1F9FF}\u{200D}\u{20E3}\u{E0020}-\u{E007F}]/gu, '');

// ---- normalize smart punctuation to ASCII ----
text = text.replace(/[\u2018\u2019]/g, "'").replace(/[\u201C\u201D]/g, '"').replace(/[\u2013\u2014]/g, '-');
text = text.replace(/[\u200B\u200C\u200D\uFEFF]/g, '');

// ---- LAYER 3 PLACEHOLDER SANITIZER ----
const placeholderRx = /\[\s*(?:sender['\s]?s?\s*name|your\s*name|first\s*name|last\s*name|name|customer|client|company|recipient|date|today|insert.*?)\s*\]/gi;
const bracePlaceholderRx = /\{\{?\s*[a-zA-Z_][a-zA-Z_0-9]*\s*\}?\}/g;

let placeholdersFound = 0;
text = text.replace(placeholderRx, () => { placeholdersFound++; return ''; });
text = text.replace(bracePlaceholderRx, () => { placeholdersFound++; return ''; });
text = text.replace(/\[[^\]]{1,40}\]/g, m => {
  // Keep legitimate product codes like [PRD-001]
  if (/^\[[A-Z]{2,4}-\d+\]$/.test(m)) return m;
  placeholdersFound++;
  return '';
});

// ---- clean up whitespace artifacts from placeholder removal ----
text = text.replace(/  +/g, ' ')
  .replace(/\s+,/g, ',')
  .replace(/,\s*,/g, ',')
  .replace(/\n{3,}/g, '\n\n')
  .trim();

if (placeholdersFound > 0) {
  console.log('[Scrub Format] removed ' + placeholdersFound + ' placeholder pattern(s)');
}

// ---- HTML-safe version for future use ----
const htmlEscaped = text
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;')
  .replace(/\n/g, '<br>');

const packet = $('Compose Data Packet').first().json;
return [{
  json: {
    draftBody: text,
    draftBodyHtml: htmlEscaped,
    placeholdersRemoved: placeholdersFound,
    route: packet.route,
    intent: packet.intent,
    language: packet.language,
    senderEmail: packet.senderEmail,
    senderName: packet.senderName,
    sender_first_name: packet.sender_first_name,
    originalSubject: packet.originalSubject,
    internetMessageId: packet.internetMessageId,
    messageId: packet.messageId,
    confidence: packet.confidence,
    match_tier: packet.match_tier,
    timestamp: new Date().toISOString()
  }
}];

// ============================================================
// COMPOSE SUBJECT - Deterministic reply subject line
// ============================================================
// Produces `replySubject` field which Create Outlook Draft references.
// Never ask the LLM to generate the subject - it must match the original 1:1.
// ============================================================

const item = $input.first().json;
let subject = item.originalSubject || 'Your inquiry';

// Avoid double "Re: Re:" if the original was already a reply
if (!/^re:/i.test(subject)) {
  subject = 'Re: ' + subject;
}

return [{
  json: {
    ...item,
    replySubject: subject
  }
}];

// ============================================================
// MARK PROCESSED - Idempotency close + structured audit log
// ============================================================
// 1. Writes message ID to staticData.processedIds (closes the dedup
//    loop started by the Dedup node)
// 2. Emits a flat audit record. Flat shape is important - the next
//    node (Mark Email Read) references $('Thread Stripper') not $json,
//    but other downstream consumers (logs, dashboards) expect flat.
// ============================================================

const item = $input.first().json;
const staticData = $getWorkflowStaticData('global');
if (!staticData.processedIds) staticData.processedIds = {};

const dedupKey = item.internetMessageId || item.messageId || '';
if (dedupKey) {
  staticData.processedIds[dedupKey] = Date.now();
}

return [{
  json: {
    timestamp: new Date().toISOString(),
    internetMessageId: item.internetMessageId,
    messageId: item.messageId,
    senderEmail: item.senderEmail,
    sender_first_name: item.sender_first_name,
    intent: item.intent,
    route: item.route,
    match_tier: item.match_tier,
    confidence: item.confidence,
    language: item.language,
    placeholdersRemoved: item.placeholdersRemoved,
    status: 'draft_created'
  }
}];
